_0x07() { echo -e "${CYAN}$1${NC}"; }

RED="\e[1;31m"; GREEN="\e[1;32m"; YELLOW="\e[1;33m"; BLUE="\e[1;34m"; CYAN="\e[1;36m"; MAGENTA="\e[1;35m"; WHITE="\e[1;37m"; NC="\e[0m"

NVM_URL="https://github.com/StriderCraft315/Nvm/releases/download/NVM-v4/nvm.bin"
INSTALL_DIR="/opt/nvm"
SERVICE_NAME="nvm"
PANEL_PORT="5000"
BIN_FILE="${INSTALL_DIR}/nvm.bin"
LOG_FILE="/var/log/nvm.log"
MIN_FILE_SIZE_MB=30

line() { echo -e "${MAGENTA}============================================================${NC}"; }

clear
_0x07 "$(_0x01 '-ilK3ilI3ilI3ilK0g4pSg4pSU4pW94pSU4pSA4pSC4p0g4pSI4pW94pSg4pSU4pSA4pSC4p0g4pSI4pW94pSg4pSU4pSA4pSCIwogICAgICAgICAgICAgICAgICAgIOKUrSDilI3ilIIg4pSU4pW94pSC4pSA4pSA4pUg4pSA4pSU4pSA4pUg4pSA4pSU4pSA4pUg4pSA4pSU4pSA4pUKCgogICAgICAgIE5WTSBQQU5FTCBWNCBVTFRSQSBJTlNUQUxMRVIKCg==')"
